<script setup lang="ts">definePageMeta({layout:'admin'});const {data}=await useFetch('/api/admin/settings',{transform:(r:any)=>r.data});const f=reactive({business_name:'ProShop',tagline:'Produsen Bantal, Guling & Kasur',whatsapp:'',address:'',email:'',service_hours:'',hero_eyebrow:'PRODUK TIDUR BUATAN LOKAL',hero_title:'',hero_description:'',hero_cta:'Lihat Produk',default_low_stock_threshold:'5'});watch(data,v=>Object.assign(f,v||{}),{immediate:true});const message=ref(''),error=ref('');async function save(){message.value='';error.value='';try{await $fetch('/api/admin/settings',{method:'PUT',body:f});message.value='Pengaturan berhasil disimpan.'}catch(e:any){error.value=e.data?.statusMessage||'Gagal menyimpan pengaturan.'}}</script><template><form class="admin-page" @submit.prevent="save"><AdminPageHeader title="Pengaturan" description="Informasi toko dan konten utama yang penting."/><section class="panel block"><h2>Store</h2><div class="form-grid"><div><label class="label">Nama bisnis</label><input v-model="f.business_name" class="field"></div><div><label class="label">Tagline</label><input v-model="f.tagline" class="field"></div><div><label class="label">WhatsApp (format E.164)</label><input v-model="f.whatsapp" class="field" placeholder="62812..."></div><div><label class="label">Email</label><input v-model="f.email" class="field" type="email"></div><div><label class="label">Alamat</label><input v-model="f.address" class="field"></div><div><label class="label">Jam layanan</label><input v-model="f.service_hours" class="field"></div></div></section><section class="panel block"><h2>Homepage</h2><div><label class="label">Eyebrow</label><input v-model="f.hero_eyebrow" class="field"></div><div><label class="label">Judul hero</label><input v-model="f.hero_title" class="field"></div><div><label class="label">Deskripsi hero</label><textarea v-model="f.hero_description" class="field" rows="3"/></div><div><label class="label">Label CTA</label><input v-model="f.hero_cta" class="field"></div></section><section class="panel block"><h2>Inventory</h2><div><label class="label">Default batas stok menipis</label><input v-model="f.default_low_stock_threshold" class="field narrow" type="number" min="0"></div></section><p v-if="message" class="success">{{message}}</p><p v-if="error" class="error">{{error}}</p><button class="btn btn-primary save">Simpan pengaturan</button></form></template><style scoped>.block{padding:1.3rem;display:grid;gap:1rem}.block h2{font-size:1rem;margin:0}.narrow{max-width:180px}.success{color:var(--success)}.save{justify-self:end}</style>
